const form=document.querySelector('.event-registration-form');
const params=new URLSearchParams(location.search);const requestedEvent=params.get('event');const requestedSource=params.get('source')==='portal'?'portal':'public';
let selectedEvent=null;let sessionUser=null;let resultData=null;
const $=selector=>document.querySelector(selector);
const dateFrom=value=>new Date(`${String(value).slice(0,10)}T12:00:00`);
const fullDate=value=>dateFrom(value).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});

function showEvent(event){selectedEvent=event;const date=dateFrom(event.startDate);$('[data-event-day]').textContent=String(date.getDate()).padStart(2,'0');$('[data-event-month]').textContent=date.toLocaleDateString('pt-BR',{month:'short'}).replace('.','');$('[data-event-title]').textContent=event.title;$('[data-event-description]').textContent=event.description||'Um encontro para fortalecer propósito, direção e boas conexões.';$('[data-event-full-date]').textContent=fullDate(event.startDate);$('[data-event-time]').textContent=event.timeLabel||'Horário a confirmar';$('[data-event-location]').textContent=event.location||'Local a confirmar'}
function showGate(message,href){form.hidden=true;const gate=$('[data-account-gate]');gate.hidden=false;gate.querySelector('strong').textContent=message;gate.querySelector('[data-account-link]').href=href}
function clearErrors(){document.querySelectorAll('.field-error').forEach(item=>item.textContent='');form.querySelectorAll('.is-invalid').forEach(item=>item.classList.remove('is-invalid'))}
function setErrors(fields={}){Object.entries(fields).forEach(([name,message])=>{const output=form.querySelector(`[data-error-for="${name}"]`);if(output)output.textContent=message;const input=name==='fullName'?form.querySelector('[name="attendeeName"]'):form.elements[name];if(input)input.classList.add('is-invalid')})}
function digits(value){return String(value||'').replace(/\D/g,'')}
function maskCnpj(value){const d=digits(value).slice(0,14);let output=d.slice(0,2);if(d.length>2)output+=`.${d.slice(2,5)}`;if(d.length>5)output+=`.${d.slice(5,8)}`;if(d.length>8)output+=`/${d.slice(8,12)}`;if(d.length>12)output+=`-${d.slice(12,14)}`;return output}
function maskPhone(value){const d=digits(value).slice(0,11);return d.length<=10?d.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{4})(\d)/,'$1-$2'):d.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{5})(\d)/,'$1-$2')}
form.elements.cnpj.addEventListener('input',event=>event.target.value=maskCnpj(event.target.value));form.elements.whatsapp.addEventListener('input',event=>event.target.value=maskPhone(event.target.value));

function addAttendee(){const row=document.createElement('div');row.className='attendee-row';row.innerHTML='<label>Nome completo<input name="attendeeName" maxlength="100" required></label><button type="button" aria-label="Remover participante">Remover</button>';row.querySelector('button').onclick=()=>row.remove();$('[data-attendee-list]').append(row);row.querySelector('input').focus()}
$('[data-add-attendee]').addEventListener('click',addAttendee);

function wrapText(ctx,text,x,y,maxWidth,lineHeight,maxLines=3){const words=String(text).split(' ');let line='';let lines=0;for(const word of words){const test=`${line}${word} `;if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line.trim(),x,y);y+=lineHeight;line=`${word} `;lines++;if(lines>=maxLines)return y}else line=test}if(line&&lines<maxLines){ctx.fillText(line.trim(),x,y);y+=lineHeight}return y}
function downloadInvite(){if(!resultData)return;const {registration,event}=resultData;const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1500;const ctx=canvas.getContext('2d');const gradient=ctx.createLinearGradient(0,0,1200,1500);gradient.addColorStop(0,'#171719');gradient.addColorStop(1,'#050506');ctx.fillStyle=gradient;ctx.fillRect(0,0,1200,1500);ctx.strokeStyle='#f1c75b';ctx.lineWidth=4;ctx.strokeRect(48,48,1104,1404);ctx.textAlign='center';ctx.fillStyle='#f1c75b';ctx.font='600 28px Arial';ctx.fillText('A FONTE DO EMPREENDEDOR',600,150);ctx.font='500 22px Arial';ctx.fillText('CONVITE OFICIAL',600,220);ctx.fillStyle='#ffffff';ctx.font='700 70px Arial';let y=wrapText(ctx,event.title,600,380,930,82,3);ctx.fillStyle='#c9c4bb';ctx.font='400 30px Arial';ctx.fillText(fullDate(event.startDate),600,y+45);ctx.fillText([event.timeLabel,event.location].filter(Boolean).join(' • '),600,y+92);ctx.strokeStyle='rgba(241,199,91,.35)';ctx.beginPath();ctx.moveTo(220,y+150);ctx.lineTo(980,y+150);ctx.stroke();ctx.fillStyle='#f1c75b';ctx.font='500 22px Arial';ctx.fillText('PARTICIPANTE',600,y+230);ctx.fillStyle='#fff';ctx.font='600 44px Arial';y=wrapText(ctx,registration.attendeeNames.join(' • '),600,y+300,900,54,4);ctx.fillStyle='#aaa69e';ctx.font='400 28px Arial';ctx.fillText(registration.companyName,600,y+35);ctx.fillStyle='#f1c75b';ctx.font='700 28px monospace';ctx.fillText(registration.inviteCode,600,1260);ctx.fillStyle='#aaa69e';ctx.font='400 22px Arial';ctx.fillText('Apresente este convite no dia do evento.',600,1340);const link=document.createElement('a');link.download=`convite-${registration.inviteCode}.png`;link.href=canvas.toDataURL('image/png');link.click()}
$('[data-download-invite]').addEventListener('click',downloadInvite);

form.addEventListener('submit',async event=>{event.preventDefault();clearErrors();const button=form.querySelector('.registration-submit');const status=form.querySelector('.form-status');button.disabled=true;status.textContent='Confirmando inscrição…';const attendeeNames=[...form.querySelectorAll('[name="attendeeName"]')].map(input=>input.value.trim()).filter(Boolean);const payload={eventId:selectedEvent?.id,source:requestedSource,attendeeNames,companyName:form.elements.companyName.value,industry:form.elements.industry.value,cnpj:form.elements.cnpj.value,whatsapp:form.elements.whatsapp.value,email:form.elements.email.value};try{const response=await fetch('/api/registrations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const data=await response.json().catch(()=>({}));if(!response.ok){setErrors(data.fields);if(data.code==='PARTNER_LOGIN_REQUIRED')showGate(data.message,'/?login=1');throw new Error(data.message||'Não foi possível concluir a inscrição.')}resultData=data;form.hidden=true;const invite=$('[data-invitation]');invite.hidden=false;$('[data-invite-event]').textContent=data.event.title;$('[data-invite-date]').textContent=fullDate(data.event.startDate);$('[data-invite-name]').textContent=data.registration.attendeeNames.join(' • ');$('[data-invite-company]').textContent=data.registration.companyName;$('[data-invite-code]').textContent=data.registration.inviteCode;invite.scrollIntoView({behavior:'smooth'})}catch(error){status.textContent=error.message}finally{button.disabled=false}});

async function start(){try{const publicResponse=await fetch('/api/public-data');if(!publicResponse.ok)throw new Error('Não foi possível carregar a programação.');const {events=[]}=await publicResponse.json();const today=new Date().toISOString().slice(0,10);const available=events.filter(event=>event.endDate>=today);showEvent(available.find(event=>event.id===requestedEvent)||available[0]);if(!selectedEvent)throw new Error('Nenhum evento está disponível para inscrição.');const sessionResponse=await fetch('/api/session');if(sessionResponse.ok){({user:sessionUser}=await sessionResponse.json());if(requestedSource!=='portal'){showGate('Você já possui cadastro. Confirme sua presença pela área do usuário.',sessionUser.role==='admin'?'/dashboard.html':'/partner.html');return}const profileResponse=await fetch('/api/profile');if(profileResponse.ok){const {profile}=await profileResponse.json();form.elements.companyName.value=profile.company_name||'';form.elements.industry.value=profile.niche||'';form.elements.cnpj.value=maskCnpj(profile.cnpj||'');form.elements.whatsapp.value=maskPhone(profile.whatsapp||'');form.elements.email.value=profile.contact_email||sessionUser.email||'';const attendee=form.querySelector('[name="attendeeName"]');if(attendee)attendee.value=profile.full_name||''}else form.elements.email.value=sessionUser.email||'';$('[data-add-attendee]').hidden=false;$('[data-attendee-help]').textContent='Adicione o nome de cada pessoa que irá pela empresa.';$('[data-form-title]').textContent='Confirme sua presença';$('[data-submit-label]').textContent='Confirmar presença'}else if(requestedSource==='portal'){showGate('Entre na sua área para confirmar presença.','/?login=1')}}catch(error){form.hidden=true;const gate=$('[data-account-gate]');gate.hidden=false;gate.querySelector('strong').textContent='Inscrição indisponível';gate.querySelector('p').textContent=error.message;gate.querySelector('a').href='/#programacao';gate.querySelector('a').firstChild.textContent='Ver programação '}}
start();
